&lt;li style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;a style=&quot;color: rgb(0, 0, 0);&quot; href=&quot;https://www.takealot.com/&quot;&gt;Minimum 4 years SQL experience&lt;/a&gt;&lt;/span&gt;&lt;/li&gt;
